-- Official SG past questions: 2017 autumn, questions 31–40.
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29a-2017-q31','exam-sg','法務・個人情報保護法','standard','single_choice','個人情報保護法が保護の対象としている個人情報に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"企業が管理している顧客情報に限られる。"},{"id":"b","text":"個人が秘密にしているプライバシー情報に限られる。"},{"id":"c","text":"生存している個人に関する情報に限られる。"},{"id":"d","text":"日本国籍を有する個人に関する情報に限られる。"}]','"c"','正解はウ。個人情報は顧客に限らず，生存する個人に関する一定の情報が対象であり，国籍や秘密性は条件ではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q32','exam-sg','法務・特定電子メール法','standard','single_choice','広告宣伝メールを「特定電子メールの送信の適正化等に関する法律」に従って送信する場合，原則として採用する方式はどれか。','[{"id":"a","text":"SMSで送信する場合はオプトアウト方式"},{"id":"b","text":"オプトイン方式とオプトアウト方式を自由に選択する"},{"id":"c","text":"原則としてオプトアウト方式"},{"id":"d","text":"原則としてオプトイン方式"}]','"d"','正解はエ。原則として事前に受信者の同意を得るオプトイン方式が必要である（一部例外あり）。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q33','exam-sg','法務・著作権','standard','single_choice','著作権法において，保護の対象となり得ないものはどれか。','[{"id":"a","text":"インターネットで公開されたフリーソフトウェア"},{"id":"b","text":"ソフトウェアの操作マニュアル"},{"id":"c","text":"データベース"},{"id":"d","text":"プログラム言語や規約"}]','"d"','正解はエ。プログラム言語，規約及び解法は，著作権法による保護の対象外とされる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q34','exam-sg','法務・不正競争防止法','standard','single_choice','不正の利益を得る目的で，他社の商標名と類似したドメイン名を登録するなどの行為を規制する法律はどれか。','[{"id":"a","text":"独占禁止法"},{"id":"b","text":"特定商取引法"},{"id":"c","text":"不正アクセス禁止法"},{"id":"d","text":"不正競争防止法"}]','"d"','正解はエ。不正の利益を得る目的などで他人の商品等表示に類似したドメイン名を使用する行為は，不正競争防止法の規制対象となり得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q35','exam-sg','法務・ソフトウェアライセンス','standard','single_choice','インストール台数を条件とするソフトウェアXのライセンスをPC100台分購入した。使用許諾契約を遵守している対応はどれか。','[{"id":"a","text":"PC10台を他部署へ移動させたが，ソフトウェアXを消去せず移動先で使用する。"},{"id":"b","text":"新規PC10台に追加購入せずソフトウェアXをインストールする。"},{"id":"c","text":"販売停止後はライセンス管理を中止し，自由にインストールする。"},{"id":"d","text":"100台を超えてインストールするが，同時利用は100台以下にする。"}]','"a"','正解はア。PCを移動してもインストール台数は増えない。一方，インストール台数を条件とするライセンスでは同時利用台数だけでは判断しない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q36','exam-sg','法務・労働者派遣法','standard','single_choice','労働者派遣法に照らして適切な行為はどれか。','[{"id":"a","text":"派遣期間を3年とする契約を結ぶ。"},{"id":"b","text":"派遣候補者の履歴書を求めて書類選考を行う。"},{"id":"c","text":"20代男性の派遣を依頼する。"},{"id":"d","text":"派遣労働者からの苦情処理を派遣元だけに任せる。"}]','"a"','正解はア。一定の条件下で同一組織単位における派遣期間は最長3年。派遣労働者の特定を目的とする選考や性別・年齢を指定する行為は不適切である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q37','exam-sg','内部統制・スプレッドシート','standard','single_choice','スプレッドシート利用時に財務データの誤りを発見するために有効な統制はどれか。','[{"id":"a","text":"更新不要なシートを閲覧専用にロックする。"},{"id":"b","text":"入力データと入力原票を照合する。"},{"id":"c","text":"変更申請を上長が事前承認する。"},{"id":"d","text":"スプレッドシートを定期的にバックアップする。"}]','"b"','正解はイ。入力データと原票を照合することで，入力時の誤りを発見できる。ロックや承認は改ざん防止，バックアップはデータ滅失対策に有効である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q38','exam-sg','内部統制・コントロールトータル','standard','single_choice','入出金管理システムから売掛金管理システムへ受け渡すデータの正確性及び網羅性を確保するコントロールはどれか。','[{"id":"a","text":"入力データと出力結果とのランツーランコントロール"},{"id":"b","text":"マスタファイル更新のタイムスタンプ機能"},{"id":"c","text":"入金額及び入金データ件数のコントロールトータルチェック"},{"id":"d","text":"入力時のエディットバリデーションチェック"}]','"c"','正解はウ。コントロールトータルは金額合計や件数を照合し，データの正確性・完全性を確認する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q39','exam-sg','システム監査・監査目的','standard','single_choice','システム監査基準（平成16年）における，組織体がシステム監査を実施する目的はどれか。','[{"id":"a","text":"自社の強み・弱みと機会・脅威を整理し，経営戦略を設定する。"},{"id":"b","text":"運用部門のテストでネットワークの脆弱性を調べる。"},{"id":"c","text":"情報システムのリスクに対するコントロールの整備・運用状況を評価し，改善につなげる。"},{"id":"d","text":"開発組織の生産性レベルを測り，より高い生産性を目指す。"}]','"c"','正解はウ。システム監査は情報システムのリスクに対するコントロールを独立した立場から評価し，ITガバナンスの実現に寄与する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q40','exam-sg','システム監査・監査調書','standard','single_choice','監査調書の説明はどれか。','[{"id":"a","text":"監査人が行った監査手続の実施記録であり，監査意見の根拠となる。"},{"id":"b","text":"監査人が被監査部門に提出するセキュリティ誓約書をまとめたもの。"},{"id":"c","text":"監査に利用した基準書やガイドラインをまとめたもの。"},{"id":"d","text":"監査人の注意義務を証明するため監査報告書とともに公表するもの。"}]','"a"','正解はア。監査調書は実施した監査手続，収集した証拠，分析及び結論を記録し，監査結果の裏付けとなる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja');
